import sys

def find_square_sides(n):
    for m in range(1, int(n**0.5) + 1):
        k_squared = m*m - n
        k = int(k_squared**0.5)
        if k*k == k_squared:
            return m, k
    return "impossible"

input = sys.stdin.read().strip()
print(find_square_sides(int(input)))

