import sys

def find_dimensions(n):
    for k in range(int(n**0.5) + 1):
        if (n + k * k) % 2 == 0:
            m_squared = (n + k * k) // 2
            m = int(m_squared**0.5)
            if m * m == m_squared:
                return m, k
    return "impossible"

